mapper.update:
update aiedu_classroom_session
set current_stage = #{currentStage,jdbcType=VARCHAR}
where classroom_id = #{classroomId,jdbcType=INTEGER}

mapper.select:
select id, class_id, classroom_id, classroom_name, teacher_id, teacher_name, class_code, current_stage,
       status, grade, ai_tool_json, courseware_json, quiz_config_json, created_at, updated_at
from aiedu_classroom_session
where status = 'active'
and classroom_id = #{classroomId}
and teacher_id = #{teacherId}
and class_id = #{classId}
